					sink.approve(SUBJECT, PREDICATE, VF.createLiteral("committed"), null);
					sink.approve(NAMED_SUBJECT, PREDICATE, VF.createLiteral("committed"), CONTEXT);
					sink.setNamespace("admission", "urn:publication-admission:");
